def generate_color_code(n, P):
    # Initialize the queue with the starting state
    queue = deque([('0' * n, 0)])
    visited = set(['0' * n])
    result = []

    while queue:
        current, depth = queue.popleft()
        result.append(current)

        if len(result) == 1 << n:
            # Check if the last two elements differ in exactly P
            if int(result[-1], 2) ^ int(result[0], 2) in P:
                return result

        for i in range(n):
            # Flip the i-th bit to get the next state
            next_code = current[:i] + ('1' if current[i] == '0' else '0') + current[i+1:]
            if next_code not in visited and int(next_code, 2) ^ int(current, 2) in P:
                visited.add(next_code)
                queue.append((next_code, depth + 1))

    return None

